mapper.select:
SELECT bs.branch_stock_code AS branchStockCode, bs.material_code AS materialCode, mg.group_name AS categoryName, m.material_name AS materialName, m.unit AS unit, COALESCE(bmss.safe_stock_qty, 0) AS safeStockQty
FROM branch_stock bs JOIN material m ON bs.material_code = m.material_code LEFT JOIN material_group mg ON m.material_group_id = mg.material_group_id LEFT JOIN branch_material_safety_stock bmss ON bmss.branch_code = bs.branch_code AND bmss.material_code = bs.material_code
WHERE bs.branch_code = #{branchCode}
AND mg.group_name = #{categoryName}
AND m.material_name = #{itemName}
GROUP BY bs.branch_stock_code, bs.material_code, mg.group_name, m.material_name, m.unit, bmss.safe_stock_qty ORDER BY mg.group_name, m.material_name
